import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

interface NodeConfig {
  imageUrl?: string;
  depthMapUrl?: string;
  meshUrl?: string;
  textContent?: Array<{
    text: string;
    role?: string;
    typography?: {
      fontSize?: number;
    };
  }>;
  cinematicPrimitives?: Array<{
    name: string;
    params?: Record<string, unknown>;
    trigger?: string;
  }>;
  intent?: {
    visualSpec?: {
      textContent?: NodeConfig['textContent'];
      colors?: Record<string, string>;
    };
  };
}

interface NodeContext {
  THREE: typeof import('three/webgpu');
  textureLoader: {
    loadTexture(url: string): Promise<import('three/webgpu').Texture>;
  };
  glbLoader: {
    loadGLB(url: string): Promise<{ scene: import('three/webgpu').Object3D }>;
  };
  fontAtlas: {
    createText(
      content: string,
      opts?: {
        fontSize?: number;
        color?: import('three/webgpu').ColorRepresentation;
        align?: 'left' | 'center' | 'right';
        maxWidthPx?: number;
        letterSpacingPx?: number;
      }
    ): import('three/webgpu').Object3D;
  };
  primitives: Record<
    string,
    (
      target: import('three/webgpu').Object3D,
      params?: Record<string, unknown>
    ) => { timeline?: { kill?: () => void }; cleanup?: () => void }
  >;
  emit(event: string, payload?: unknown): void;
  tier?: 'T0' | 'T1' | 'T2';
}

export default function createNode(
  config: NodeConfig,
  ctx: NodeContext
): import('three/webgpu').Object3D {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color,
    Vector3,
  } = ctx.THREE;

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const root = new Group();
  root.name = 'journal-thumbnail-card';

  const card = new Group();
  card.name = 'thumbnail-card-body';
  root.add(card);

  const timelines: Array<{ kill?: () => void }> = [];
  const primitiveCleanups: Array<() => void> = [];
  const ownedResources: Array<{ dispose?: () => void }> = [];

  const panelGeometry = new BoxGeometry(3.05, 2.2, 0.12);
  const panelMaterial = new MeshBasicNodeMaterial({
    color: new Color(ink),
    roughness: 0.72,
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.name = 'machined-card-panel';
  panel.position.z = -0.09;
  card.add(panel);
  ownedResources.push(panelGeometry, panelMaterial);

  const imageGeometry = new PlaneGeometry(2.85, 1.78);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: new Color(paper),
  });
  const image = new Mesh(imageGeometry, imageMaterial);
  image.name = 'journal-thumbnail-image';
  image.position.z = 0.015;
  card.add(image);
  ownedResources.push(imageGeometry, imageMaterial);

  const captionGeometry = new BoxGeometry(2.85, 0.34, 0.035);
  const captionMaterial = new MeshBasicNodeMaterial({
    color: new Color(surface),
  });
  const captionStrip = new Mesh(captionGeometry, captionMaterial);
  captionStrip.name = 'caption-strip';
  captionStrip.position.set(0, -0.88, 0.055);
  card.add(captionStrip);
  ownedResources.push(captionGeometry, captionMaterial);

  const accentGeometry = new BoxGeometry(0.045, 1.78, 0.045);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color(accent),
    transparent: true,
    opacity: 0.92,
  });
  const accentEdge = new Mesh(accentGeometry, accentMaterial);
  accentEdge.name = 'accent-focus-edge';
  accentEdge.position.set(-1.425, 0, 0.085);
  accentEdge.visible = false;
  card.add(accentEdge);
  ownedResources.push(accentGeometry, accentMaterial);

  const topAccentGeometry = new BoxGeometry(2.85, 0.025, 0.045);
  const topAccent = new Mesh(
    topAccentGeometry,
    new MeshBasicNodeMaterial({
      color: new Color(accent),
      transparent: true,
      opacity: 0.8,
    })
  );
  topAccent.name = 'accent-caption-rule';
  topAccent.position.set(0, -0.69, 0.085);
  card.add(topAccent);
  ownedResources.push(topAccentGeometry, topAccent.material);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      imageMaterial.map = texture;
      imageMaterial.color.set('#ffffff');
      imageMaterial.needsUpdate = true;
      ownedResources.push(texture);
    }).catch(() => {
      imageMaterial.color.set(surface);
      imageMaterial.needsUpdate = true;
    });
  } else {
    imageMaterial.color.set(surface);
    imageMaterial.needsUpdate = true;
  }

  const baseY = card.position.y;
  let hoverTimeline: { kill?: () => void } | undefined;

  const showFocusEdge = () => {
    accentEdge.visible = true;
    gsap.to(accentMaterial, {
      opacity: 1,
      duration: 0.18,
      ease: 'power2.out',
    });
  };

  const hideFocusEdge = () => {
    gsap.to(accentMaterial, {
      opacity: 0,
      duration: 0.2,
      ease: 'power2.out',
      onComplete: () => {
        accentEdge.visible = false;
      },
    });
  };

  const hoverIn = () => {
    hoverTimeline?.kill?.();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(card.position, {
      y: baseY + 0.15,
      duration: 0.45,
      ease: 'power3.out',
    });
    hoverTimeline.to(card.rotation, {
      x: -0.025,
      y: 0.025,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    showFocusEdge();
  };

  const hoverOut = () => {
    hoverTimeline?.kill?.();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(card.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power3.out',
    });
    hoverTimeline.to(card.rotation, {
      x: 0,
      y: 0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    hideFocusEdge();
  };

  const press = () => {
    const pressTimeline = gsap.timeline();
    pressTimeline.to(card.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out',
    });
    pressTimeline.to(card.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.42,
      ease: 'back.out(1.7)',
    });
    timelines.push(pressTimeline);
    ctx.emit('hub-journal.select', {
      node: 'journal-thumbnail-card',
      imageUrl: config.imageUrl,
    });
  };

  root.userData.handlers = {
    hover: hoverIn,
    hoverStart: hoverIn,
    hoverEnd: hoverOut,
    pointerover: hoverIn,
    pointerout: hoverOut,
    focus: showFocusEdge,
    blur: hideFocusEdge,
    click: press,
  };

  root.userData.cleanup = () => {
    hoverTimeline?.kill?.();
    for (const timeline of timelines) timeline.kill?.();
    for (const cleanup of primitiveCleanups) cleanup();
    for (const resource of ownedResources) resource.dispose?.();
  };

  return root;
}
